import SwiftUI

struct SettingsView: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; @State private var showPlus = false; var body: some View { NavigationStack { Form { Section("Внешний вид") { Picker("Тема", selection: $store.settings.theme) { Text("Система").tag(AppTheme.system); Text("Светлая").tag(AppTheme.light); Text("Тёмная").tag(AppTheme.dark) }; Picker("Акцент", selection: $store.settings.accent) { ForEach(AccentTheme.allCases, id: \.self) { Text($0.rawValue.capitalized).tag($0) } }; Toggle("Уменьшить анимации", isOn: $store.settings.reduceMotion) }; Section("Язык и деньги") { Picker("Язык", selection: $store.settings.language) { Text("Русский").tag(AppLanguage.russian); Text("English").tag(AppLanguage.english) }; Picker("Валюта", selection: $store.settings.currency) { ForEach(["€", "$", "₴", "₽", "£"], id: \.self) { Text($0).tag($0) } } }; Section("Уведомления") { Toggle("Напоминания Флами", isOn: $store.settings.notifications).onChange(of: store.settings.notifications) { _, _ in Task { await store.requestNotifications() } }; Text("Флами напомнит покормить питомца, поиграть и пожелает удачи перед сменой.").font(.caption).foregroundStyle(.secondary) }; Section("Flamio+") { Button { showPlus = true } label: { HStack { Text("👑"); VStack(alignment: .leading) { Text("Flamio+").font(.headline); Text("Больше образов, аналитика и виджеты").font(.caption).foregroundStyle(.secondary) }; Spacer(); Text("€2.49").foregroundStyle(.orange) } } }; Section("Виджет") { Text("App Group: \(FlamioShared.appGroup)").font(.caption.monospaced()).foregroundStyle(.secondary); Text("Для серого виджета включи эту группу в профилях приложения и Widget Extension в Apple Developer / Codemagic.").font(.caption).foregroundStyle(.secondary) } }.navigationTitle("Настройки").toolbar { Button("Готово") { dismiss() } }.sheet(isPresented: $showPlus) { PlusView() } } } }
struct PlusView: View { @Environment(\.dismiss) var dismiss; var body: some View { VStack(spacing: 18) { Text("👑").font(.system(size: 70)); Text("Flamio+").font(.largeTitle.bold()); Text("Спокойнее планируй день и заботься о Флами без ограничений.").multilineTextAlignment(.center).foregroundStyle(.secondary); VStack(alignment: .leading, spacing: 12) { Label("Расширенная аналитика смен и денег", systemImage: "chart.xyaxis.line"); Label("Эксклюзивные наряды и игры", systemImage: "sparkles"); Label("Умные напоминания и темы", systemImage: "bell.badge.fill") }; Spacer(); Text("€2.49 · $2.49 · 99 ₴ / месяц").font(.headline); Button("Оформить подписку") {}.buttonStyle(.borderedProminent).controlSize(.large); Text("Цена в App Store может отличаться по региону. StoreKit подключается после создания продукта в App Store Connect.").font(.caption).multilineTextAlignment(.center).foregroundStyle(.secondary); Button("Закрыть") { dismiss() } }.padding(28) } }
